import { existsSync } from "node:fs";
import { playgroundUrl, publicUrl } from "../shared/env";

let ready = true;
for (const name of ["STEEL_API_KEY", "ANTHROPIC_API_KEY", "EXPANDTESTING_USERNAME", "EXPANDTESTING_PASSWORD"]) {
  const configured = Boolean(process.env[name]);
  console.log(`${configured ? "PASS" : "SET"} ${name}`);
  if (!configured) ready = false;
}
try { console.log("PASS public target:", publicUrl(playgroundUrl()).href); }
catch { console.log("SET PLAYGROUND_URL for example 06 (not needed for 01–05)"); ready = false; }
if (!existsSync("assets/robot.png")) { console.log("MISSING assets/robot.png"); ready = false; }
console.log("Configuration only. Run the numbered examples to verify Steel and Anthropic.");
if (!ready) process.exitCode = 1;

import { readFile } from "node:fs/promises";
import { localBrowser } from "./local-browser";
const browser = await localBrowser();
try {
  const page = await browser.newPage({ viewport: { width: 1000, height: 800 }, deviceScaleFactor: 1 });
  const svg = await readFile("assets/robot.svg", "utf8");
  await page.setContent(`<html><body style="margin:0">${svg}</body></html>`);
  await page.screenshot({ path: "assets/robot.png" });
  console.log("Generated the original workshop robot image.");
} finally { await browser.close(); }

import { randomUUID } from "node:crypto";
import type { Page } from "playwright";

// Each observation replaces the element refs.
export async function observe(page: Page) {
  return page.evaluate(prefix => {
    document.querySelectorAll("[data-workshop-ref]").forEach(el => el.removeAttribute("data-workshop-ref"));
    const elements = Array.from(document.querySelectorAll<HTMLElement>(
      'a[href],button,input,textarea,select,[role="button"],[contenteditable="true"]',
    )).filter(el => el.getClientRects().length || (el instanceof HTMLInputElement && el.type === "file"))
      .slice(0, 100).map((el, i) => {
        const ref = `${prefix}-${i}`;
        el.setAttribute("data-workshop-ref", ref);
        const labels = "labels" in el ? Array.from((el as HTMLInputElement).labels ?? []).map(l => l.textContent).join(" ") : "";
        return { ref, tag: el.tagName.toLowerCase(), type: el.getAttribute("type"),
          checked: el instanceof HTMLInputElement && el.type === "checkbox" ? el.checked : undefined,
          label: (el.getAttribute("aria-label") || labels || el.getAttribute("placeholder") || el.innerText || el.getAttribute("name") || "").trim().slice(0, 160) };
      });
    return { url: location.href, text: document.body.innerText.slice(0, 8000), elements };
  }, `r${randomUUID().replaceAll("-", "")}`);
}
export function selector(ref: string) {
  if (!/^r[a-f0-9]{32}-\d+$/.test(ref)) throw new Error("Use a ref from the latest observation.");
  return `[data-workshop-ref="${ref}"]`;
}

import { config } from "dotenv";
config({ path: ".env.local", quiet: true });

export function required(name: string) {
  const value = process.env[name];
  if (!value) throw new Error(`Set ${name} in .env.local.`);
  return value;
}
export function playgroundUrl() {
  return (process.env.PLAYGROUND_URL || "http://127.0.0.1:4400").replace(/\/$/, "");
}
export function publicUrl(value: string) {
  const url = new URL(value);
  if (!["http:", "https:"].includes(url.protocol)) throw new Error("Use an HTTP(S) URL.");
  if (["localhost", "127.0.0.1", "0.0.0.0", "[::1]"].includes(url.hostname)) {
    throw new Error("Steel Cloud cannot reach laptop localhost. Set PLAYGROUND_URL to the playground's public tunnel URL; see README.md.");
  }
  return url;
}
export function safeError(error: unknown) {
  let message = error instanceof Error ? error.message : String(error);
  for (const [name, value] of Object.entries(process.env)) {
    if (/(API_KEY|PASSWORD|COOKIE_SECRET)$/.test(name) && value) {
      message = message.replaceAll(value, "[redacted]").replaceAll(encodeURIComponent(value), "[redacted]");
    }
  }
  return message.replace(/([?&](?:apiKey|token)=)[^&\s"']+/gi, "$1[redacted]").slice(0, 1500);
}

import { createInterface } from "node:readline/promises";
import { safeError } from "./env";

export async function run(task: () => Promise<void>) {
  try { await task(); }
  catch (error) { console.error(safeError(error)); process.exitCode = 1; }
}
export async function waitForEnter(message: string) {
  if (!process.stdin.isTTY) throw new Error("Run this interactive example in a terminal.");
  const terminal = createInterface({ input: process.stdin, output: process.stdout });
  try { await terminal.question(`${message}\nPress Enter to continue. `); }
  finally { terminal.close(); }
}
export async function pause(message: string) {
  if (process.argv.includes("--watch")) await waitForEnter(message);
}

import "../shared/env";
import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const folder = path.dirname(fileURLToPath(import.meta.url));
const server = createServer(async (request, response) => {
  try {
    const url = new URL(request.url || "/", "http://playground");
    response.setHeader("Cache-Control", "no-store");
    response.setHeader("X-Content-Type-Options", "nosniff");
    if (url.pathname === "/") { response.writeHead(302, { Location: "/meme" }); response.end(); return; }
    if (url.pathname === "/health") { response.setHeader("Content-Type", "application/json"); response.end(JSON.stringify({ ok: true, target: "steel-hackathon-playground" })); return; }
    if (url.pathname === "/assets/robot.png") { response.setHeader("Content-Type", "image/png"); response.end(await readFile(path.join(folder, "../assets/robot.png"))); return; }
    response.setHeader("Content-Type", "text/html; charset=utf-8");
    if (url.pathname === "/meme") { response.end(await readFile(path.join(folder, "meme.html"), "utf8")); return; }
    response.writeHead(404); response.end("Page not found");
  } catch { response.writeHead(500); response.end("The playground could not handle this request."); }
});
const port = Number(process.env.PLAYGROUND_PORT || 4400);
server.listen(port, "127.0.0.1", () => console.log(`Playground ready at http://127.0.0.1:${port}. Set PLAYGROUND_URL to its public tunnel URL for example 06.`));
